module main(A, B, multiply, Result, Cout);

    input [3:0] A;
    input [1:0] B;
    input multiply;
    output [4:0] Result;
    output Cout;

    // Wires for the partial products generated by the 'multiplier' sub-module.
    wire [3:0] p1;
    wire [4:0] p2_shifted;

    // Wires for the MUX outputs, which serve as the final adder inputs.
    wire [4:0] mux1_out;
    wire [4:0] mux2_out;

    // Wires for zero-extending the 4-bit and 2-bit inputs to 5-bit for consistent operation.
    wire [4:0] five_bit_p1;
    wire [4:0] five_bit_A;
    wire [4:0] five_bit_B;

    // Instantiate the Multiplier Sub-Module.
    multiplier multip (.A(A),.B(B),.p1(p1),.p2_shifted(p2_shifted));

    // Extend p1 (4-bit) by padding a leading '0' to match the 5-bit inputs of the MUX/Adder.
    assign five_bit_p1 = {1'b0,p1};

    // Extend A (4-bit) by padding a leading '0' to match the 5-bit MUX/Adder inputs.
    assign five_bit_A = {1'b0,A};

    // Extend B (2-bit) by padding three leading '0's to match the 5-bit MUX/Adder inputs.
    assign five_bit_B = {3'b000,B};

    // Instantiate Multiplexers for Operand Selection.
    five_bit_2x1_mux mux1 (.In_0(five_bit_A),.In_1(five_bit_p1),.Select(multiply),.Out(mux1_out));
    five_bit_2x1_mux mux2 (.In_0(five_bit_B),.In_1(p2_shifted),.Select(multiply),.Out(mux2_out));

    // Instantiate the Final Adder (Ripple Carry Adder).
    five_bit_rca adder (.A(mux1_out),.B(mux2_out),.Cin(1'b0),.S(Result),.Cout(Cout));

endmodule
